"""Random valid request generator."""
import json, random, sys

NUM = ("TIME","SIZE","COUNT")

def make_schema(rng, nfields):
    fields = []
    for i in range(nfields):
        kind = rng.choice(["num","id","flag"])
        name = "f%d" % i
        if kind == "num":
            t = rng.choice(NUM)
            lo = rng.choice([0,0,-10,5])
            hi = lo + rng.choice([0,1,5,100,1000])
            fields.append({"name":name,"type":t,"min":lo,"max":hi})
        elif kind == "id":
            vals = ["v%d" % j for j in range(rng.randint(1,4))]
            fields.append({"name":name,"type":"ID","values":vals})
        else:
            fields.append({"name":name,"type":"FLAG"})
    return fields

def num_field_names(fields):
    return [f["name"] for f in fields if f["type"] in NUM]

def id_field_names(fields):
    return [f["name"] for f in fields if f["type"]=="ID"]

def flag_field_names(fields):
    return [f["name"] for f in fields if f["type"]=="FLAG"]

def gen_term(rng, fields, K, typ, depth, dollar_ok):
    """Generate a term of the given type."""
    choices = ["const","field"]
    if depth < 3:
        choices += ["scale","add"]
    if typ in NUM:
        choices += ["agg"]
    kind = rng.choice(choices)
    if kind == "const":
        if typ == "FLAG": return {"const": rng.choice([True,False]), "type":"FLAG"}
        if typ == "ID": return {"const": "v%d" % rng.randint(0,3), "type":"ID"}
        return {"const": rng.randint(-5,50), "type":typ}
    if kind == "field":
        cands = [f["name"] for f in fields if f["type"]==typ]
        if not cands: return {"const": 0, "type":typ} if typ in NUM else None
        name = rng.choice(cands)
        if dollar_ok and rng.random() < 0.4:
            at = "$"
        else:
            at = rng.randrange(K)
        return {"field":name,"at":at}
    if kind == "scale":
        child = gen_term(rng, fields, K, typ, depth+1, dollar_ok)
        if child is None: return None
        return {"scale": rng.choice([-2,-1,1,2,3]), "term":child}
    if kind == "add":
        c1 = gen_term(rng, fields, K, typ, depth+1, dollar_ok)
        c2 = gen_term(rng, fields, K, typ, depth+1, dollar_ok)
        if c1 is None or c2 is None: return None
        return {"add":[c1,c2]}
    # aggregate
    cands = [f["name"] for f in fields if f["type"]==typ]
    if not cands: return None
    name = rng.choice(cands)
    lo = rng.randrange(K); hi = rng.randrange(lo, K)
    return {"aggregate": rng.choice(["sum","mean","min","max"]), "field":name, "from":lo,"to":hi}

def gen_atom(rng, fields, K):
    kinds = ["cmp","quant"]
    if rng.random() < 0.3: kinds = ["cmp"]
    if rng.random() < 0.3: kinds = ["quant"]
    kind = rng.choice(kinds)
    if kind == "cmp":
        typ = rng.choice([f["type"] for f in fields])
        op = rng.choice(["eq","ne","lt","le","gt","ge"]) if typ in NUM else rng.choice(["eq","ne"])
        left = gen_term(rng, fields, K, typ, 0, False)
        right = gen_term(rng, fields, K, typ, 0, False)
        if left is None or right is None: return None
        return {"cmp":op,"left":left,"right":right}
    else:
        typ = rng.choice([f["type"] for f in fields])
        op = rng.choice(["eq","ne","lt","le","gt","ge"]) if typ in NUM else rng.choice(["eq","ne"])
        left = gen_term(rng, fields, K, typ, 0, True)
        right = gen_term(rng, fields, K, typ, 0, True)
        if left is None or right is None: return None
        lo = rng.randrange(K); hi = rng.randrange(lo, K)
        return {"quantifier":rng.choice(["any","all"]),"from":lo,"to":hi,
                "predicate":{"cmp":op,"left":left,"right":right}}

def gen_values(rng, fields):
    out = []
    for f in fields:
        if f["type"] == "FLAG":
            out.append(rng.choice([True,False]))
        elif f["type"] == "ID":
            out.append(rng.choice(f["values"]))
        else:
            out.append(rng.randint(f["min"], min(f["max"], f["min"]+20)))
    return out

def gen_traces(rng, fields, prefix, ntraces, nsources, maxrows):
    traces = []
    for i in range(ntraces):
        nrows = rng.randint(0, maxrows)
        times = rng.sample(range(-50,50), nrows)
        rows = [{"t":t,"values":gen_values(rng,fields)} for t in times]
        traces.append({"id":"%s%d"%(prefix,i),"source":"src%d"%(rng.randrange(nsources)),"rows":rows})
    return traces

def gen_request(seed):
    rng = random.Random(seed)
    K = rng.randint(1,4)
    nfields = rng.randint(1,3)
    fields = make_schema(rng, nfields)
    atoms = []
    for _ in range(rng.randint(0,5)):
        a = gen_atom(rng, fields, K)
        if a is not None: atoms.append(a)
    req = {
        "version":1,
        "schema":fields,
        "window":K,
        "atoms":atoms,
        "policy":{"max_width":rng.randint(1,3),"min_support":rng.randint(1,2),"min_witness":rng.randint(1,2)},
        "train":gen_traces(rng,fields,"tr",rng.randint(0,3),rng.randint(1,2),6),
        "probes":gen_traces(rng,fields,"pr",rng.randint(0,2),1,5),
        "queries":gen_traces(rng,fields,"qu",rng.randint(0,2),1,5),
    }
    return req

if __name__ == "__main__":
    seed = int(sys.argv[1])
    print(json.dumps(gen_request(seed)))
